'use strict';
const LAYOUT_LAB_KEY='legionrx4_layout_lab_v2';
const LAYOUT_CONTROL_IDS=['ctl-pause','ctl-finish','ctl-plus','ctl-primary','ctl-manual','ctl-stop','ctl-skip'];
function rallySetupView(){
 const race=state.race;const step=race?.stage||'setup';return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">RALLYCROSS</div><h1>${race?esc(race.eventName):'Новое соревнование'}</h1><p>Настройка события. После запуска вся работа переходит в одноэкранный пульт.</p></div>${race&&race.stage!=='setup'?`<button class="btn primary" data-action="cockpit">Открыть пульт</button>`:''}</div>
 <div class="setupShell"><aside class="card setupSide"><div class="step ${!race||step==='setup'?'active':'done'}">1 · Событие</div><div class="step ${race&&step==='setup'?'active':race?'done':''}">2 · Пилоты</div><div class="step ${race&&step==='setup'?'active':race?'done':''}">3 · Формат</div><div class="step ${race&&step!=='setup'?'active':''}">4 · Пульт гонки</div></aside>
 <div class="grid">
  <article class="card"><div class="sectionLabel">СОБЫТИЕ</div><h2>Основные данные</h2><div class="formGrid">
   <div class="field"><label>Название</label><input id="raceName" value="${esc(race?.eventName||'Legion RX Cup')}" ${race&&race.stage!=='setup'?'disabled':''}></div>
   <div class="field"><label>Дата</label><input id="raceDate" type="date" value="${esc(race?.eventDate||new Date().toISOString().slice(0,10))}" ${race&&race.stage!=='setup'?'disabled':''}></div>
   <div class="field"><label>Место</label><input id="raceLocation" value="${esc(race?.eventLocation||'')}" placeholder="Трасса / город" ${race&&race.stage!=='setup'?'disabled':''}></div>
   <div class="field"><label>Чемпионат</label><select id="raceChamp" ${race&&race.stage!=='setup'?'disabled':''}><option value="">Клубная гонка</option>${state.championships.map(c=>`<option value="${c.id}" ${race?.championshipId===c.id?'selected':''}>${esc(c.name)} · ${esc(c.season)}</option>`).join('')}</select></div>
  </div>${!race?`<div class="btnRow" style="margin-top:14px"><button class="btn primary" data-action="create-race">Создать событие</button></div>`:''}</article>
  ${race?pilotSetupCard(race):''}
  ${race?formatSetupCard(race):''}
 </div></div></section>`;
}

function pilotSetupCard(race){return `<article class="card"><div class="pageHeader" style="margin:0 0 12px"><div><div class="sectionLabel">ПИЛОТЫ</div><h2>Участники · ${race.pilots.length}</h2></div>${race.stage==='setup'?`<div class="btnRow"><button class="btn secondary" data-action="add-db-pilot">Из базы</button><button class="btn primary" data-action="quick-pilot">＋ Новый</button></div>`:''}</div><div class="list">${race.pilots.length?race.pilots.map((p,i)=>`<div class="listRow"><div class="avatar">${nameInitials(p.name)}</div><div class="grow"><div class="name">${i+1}. ${pilotNameMarkup(p)}</div><div class="sub">${clubMarkup(pilotClubName(p),'Без клуба')} · транспондер ${esc(p.transponder||'не назначен')}</div></div>${race.stage==='setup'?`<button class="btn secondary" data-remove-race-pilot="${p.id}">Убрать</button>`:''}</div>`).join(''):`<div class="empty">Добавьте минимум двух пилотов.</div>`}</div></article>`;}

function formatSetupCard(race){
 const rs=race.raceSettings||{};
 const qType=rs.qualificationLimitType||'time',fType=rs.finalLimitType||'laps';
 return `<article class="card"><div class="sectionLabel">ФОРМАТ</div><h2>Параметры RallyCross</h2>
 <div class="formatRuleGrid">
  <section class="ruleBox"><div class="ruleBoxHead"><b>Квалификация</b><span>${race.qualifyingCount} серий</span></div><div class="formGrid">
   <div class="field"><label>Квалификационных серий</label><select id="qCount" ${race.stage!=='setup'?'disabled':''}>${[3,4,5].map(n=>`<option ${race.qualifyingCount===n?'selected':''}>${n}</option>`).join('')}</select></div>
   <div class="field"><label>Ограничение заезда</label><select id="qLimitType" ${race.stage!=='setup'?'disabled':''}><option value="time" ${qType==='time'?'selected':''}>По времени</option><option value="laps" ${qType==='laps'?'selected':''}>По кругам</option></select></div>
   <div class="field ruleConditional" data-rule-field="q-time"><label>Время, минут</label><input id="qMinutes" type="number" min="1" max="60" value="${rs.qualificationMinutes||state.settings.qualificationMinutes}" ${race.stage!=='setup'?'disabled':''}></div>
   <div class="field ruleConditional" data-rule-field="q-laps"><label>Количество кругов</label><input id="qLaps" type="number" min="1" max="999" value="${rs.qualificationLaps||state.settings.qualificationLaps}" ${race.stage!=='setup'?'disabled':''}></div>
  </div></section>
  <section class="ruleBox"><div class="ruleBoxHead"><b>Финалы / LCQ</b><span>единое правило</span></div><div class="formGrid">
   <div class="field"><label>Ограничение заезда</label><select id="finalLimitType" ${race.stage!=='setup'?'disabled':''}><option value="laps" ${fType==='laps'?'selected':''}>По кругам</option><option value="time" ${fType==='time'?'selected':''}>По времени</option></select></div>
   <div class="field ruleConditional" data-rule-field="f-laps"><label>Количество кругов</label><input id="finalLaps" type="number" min="1" max="999" value="${rs.finalLaps||state.settings.finalLaps}" ${race.stage!=='setup'?'disabled':''}></div>
   <div class="field ruleConditional" data-rule-field="f-time"><label>Время, минут</label><input id="finalMinutes" type="number" min="1" max="120" value="${rs.finalMinutes||state.settings.finalMinutes}" ${race.stage!=='setup'?'disabled':''}></div>
   <div class="field"><label>Минимальный круг LapWiz, сек</label><input id="minLap" type="number" min="1" max="60" value="${rs.minLapSec||state.settings.minLapSec}" ${race.stage!=='setup'?'disabled':''}></div>
  </div></section>
  <section class="ruleBox"><div class="ruleBoxHead"><b>Перед стартом</b><span>прогрев / проверка транспондеров</span></div><div class="formGrid">
   <div class="field"><label>Прогрев до старта, минут</label><select id="raceWarmupMinutes" ${race.stage!=='setup'?'disabled':''}>${[5,4,3,2,1].map(n=>`<option value="${n}" ${Number(rs.warmupMinutes||state.settings.warmupMinutes||2)===n?'selected':''}>${n} мин</option>`).join('')}</select></div>
   <div class="field"><label>Финальный отсчёт, секунд</label><input id="raceCountdownSec" type="number" min="1" max="10" value="${rs.countdownSec||state.settings.countdownSec||10}" ${race.stage!=='setup'?'disabled':''}></div>
  </div><p>Выбранные минуты — это всё время от нажатия СТАРТ до HORN. Финальный отсчёт входит внутрь этого времени и сверху не прибавляется.</p></section>
 </div>
 ${race.stage==='setup'?`<div class="btnRow" style="margin-top:14px"><button class="btn primary" data-action="prepare-race" ${race.pilots.length<2?'disabled':''}>Сформировать заезды и открыть пульт</button><button class="btn danger" data-action="delete-race">Удалить событие</button></div>`:`<p>Формат зафиксирован после формирования заездов, чтобы не разрушить спортивные результаты.</p>`}</article>`;
}

function championshipsView(){state.championships.forEach(normalizeChampionship);return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">СЕЗОНЫ</div><h1>Чемпионаты</h1><p>Сезон, этапы, календарь, состав пилотов и общая рейтинговая таблица.</p></div><button class="btn primary" data-action="new-champ">＋ Чемпионат</button></div><div class="grid grid2">${state.championships.length?state.championships.map(c=>champCard(c)).join(''):`<div class="card empty">Пока нет чемпионатов.</div>`}</div></section>`;}

function champCard(c){normalizeChampionship(c);const standings=champStandings(c),active=c.stagePlans.filter(s=>s.status==='active').length;return `<article class="card championshipCard"><div class="sectionLabel">${esc(c.season)}</div><div class="champTitleRow"><div><h2>${esc(c.name)}</h2><p>${c.stagePlans.length} запланировано · ${c.stages.length} завершено${active?` · ${active} активно`:''}</p></div><button class="btn primary" data-open-champ="${c.id}">Войти в чемпионат ${uiIcon('chevron','btnIcon')}</button></div>${standings.length?`<div class="tableWrap"><table class="table"><thead><tr><th>Место</th><th>Пилот</th><th>Очки</th></tr></thead><tbody>${standings.slice(0,5).map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td><b>${r.total}</b></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Нет завершённых этапов.</div>`}</article>`;}

function championshipDetailView(){
 const c=state.championships.find(x=>x.id===state.activeChampionshipId);if(!c)return `<section class="page"><div class="card empty">Чемпионат не найден.</div></section>`;normalizeChampionship(c);
 const tabs=[['stages','Этапы'],['schedule','Расписание'],['pilots','Пилоты'],['standings','Рейтинг'],['settings','Настройки']];
 return `<section class="page championshipDetail"><div class="pageHeader"><div><div class="sectionLabel">${esc(c.season)} · ЧЕМПИОНАТ</div><h1>${esc(c.name)}</h1><p>${c.stagePlans.length} этапов в календаре · ${c.stages.length} завершено</p></div><button class="btn secondary" data-action="back-champs">← Все чемпионаты</button></div><nav class="sectionTabs">${tabs.map(([k,l])=>`<button class="${state.champTab===k?'active':''}" data-champ-tab="${k}">${l}</button>`).join('')}</nav>${championshipTabContent(c)}</section>`;
}

function championshipTabContent(c){
 if(state.champTab==='settings')return `<div class="card"><div class="sectionLabel">ПАРАМЕТРЫ</div><h2>Настройки чемпионата</h2><div class="formGrid"><div class="field"><label>Название</label><input id="champNameEdit" value="${esc(c.name)}"></div><div class="field"><label>Сезон</label><input id="champSeasonEdit" type="number" value="${esc(c.season)}"></div><div class="field"><label>План этапов</label><input id="champStagesEdit" type="number" min="1" value="${c.stagesPlanned}"></div></div><div class="btnRow" style="margin-top:14px"><button class="btn primary" data-action="save-champ-settings">Сохранить</button></div></div>`;
 if(state.champTab==='schedule'){const plans=[...c.stagePlans].sort((a,b)=>(a.number||0)-(b.number||0));return `<div class="card"><div class="sectionLabel">КАЛЕНДАРЬ</div><h2>Расписание этапов</h2>${plans.length?`<div class="scheduleList">${plans.map(s=>`<div class="scheduleRow"><b>${s.number}. ${esc(s.name)}</b><span>${esc(s.date||'Дата не задана')}</span><span>${esc(s.location||'Место не задано')}</span><em class="stageStatus ${s.status||'planned'}">${stagePlanStatus(s)}</em></div>`).join('')}</div>`:`<div class="empty">Этапы ещё не добавлены.</div>`}</div>`;}
 if(state.champTab==='pilots'){const pilots=c.pilotIds.map(id=>state.pilotDb.find(p=>p.id===id)).filter(Boolean);return `<div class="card"><div class="pageHeader compactHeader"><div><div class="sectionLabel">СОСТАВ</div><h2>Пилоты чемпионата · ${pilots.length}</h2></div><button class="btn primary" data-action="champ-add-pilots">＋ Добавить из базы</button></div><div class="list">${pilots.length?pilots.map(p=>`<div class="listRow"><div class="avatar">${nameInitials(p.name)}</div><div class="grow"><div class="name">${pilotNameMarkup(p)}</div><div class="sub">${clubMarkup(p.club||'','Без клуба')} · ID ${esc(p.transponder||'—')}</div></div><button class="btn secondary" data-champ-remove-pilot="${p.id}">Убрать</button></div>`).join(''):`<div class="empty">Состав пока пуст. Можно добавить пилотов заранее или оставить этапы со своим составом.</div>`}</div></div>`;}
 if(state.champTab==='standings'){const standings=champStandings(c);return `<div class="card"><div class="sectionLabel">РЕЙТИНГ</div><h2>Таблица чемпионата</h2>${standings.length?`<div class="tableWrap"><table class="table"><thead><tr><th>POS</th><th>Пилот</th><th>Этапов</th><th>Очки</th></tr></thead><tbody>${standings.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td>${r.stages}</td><td><b>${r.total}</b></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Рейтинг появится после завершения первого этапа.</div>`}</div>`;}
 const plans=[...c.stagePlans].sort((a,b)=>(a.number||0)-(b.number||0));return `<div class="champStagesHead"><div><div class="sectionLabel">ЭТАПЫ</div><h2>Этапы чемпионата</h2></div><button class="btn primary" data-action="new-champ-stage">＋ Этап</button></div><div class="champStageGrid">${plans.length?plans.map(s=>champStageCard(c,s)).join(''):`<div class="card empty">Создайте первый этап чемпионата.</div>`}</div>`;
}

function stagePlanStatus(s){return s.status==='completed'?'Завершён':s.status==='active'?'Идёт сейчас':'Запланирован';}

function champStageCard(c,s){const activeRace=state.race&&state.race.id===s.raceId;const archived=s.raceId&&state.archive.some(r=>r.id===s.raceId);return `<article class="card champStageCard"><div class="stageCardTop"><span class="stageNo">${s.number}</span><span class="stageStatus ${s.status||'planned'}">${stagePlanStatus(s)}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.date||'Дата не задана')} · ${esc(s.location||'Место не задано')}</p><div class="btnRow"><button class="btn secondary" data-edit-stage="${s.id}">Настроить этап</button>${s.status==='completed'?`<button class="btn secondary" data-stage-results="${s.raceId||''}">Результаты</button>`:activeRace?`<button class="btn primary" data-continue-stage="${s.id}">Продолжить гонку</button>`:archived?`<button class="btn primary" data-continue-stage="${s.id}">Восстановить / продолжить</button>`:`<button class="btn primary" data-start-stage="${s.id}">Начать гонку</button>`}</div></article>`;}

function pilotsView(){return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">ОБЩАЯ БАЗА</div><h1>Пилоты</h1><p>Профиль используется во всех режимах; здесь хранятся страна, клуб и транспондер.</p></div><button class="btn primary" data-action="new-db-pilot">＋ Пилот</button></div><div class="pilotProfileGrid">${state.pilotDb.length?state.pilotDb.map(p=>`<article class="pilotProfileCard"><div class="pilotProfileAvatar">${nameInitials(p.name)}</div><div class="pilotProfileMain"><div class="pilotProfileName">${pilotNameMarkup(p)}</div><div class="pilotProfileClub">${clubMarkup(p.club||'', 'Без клуба')}</div><div class="pilotProfileMeta">${p.city?`<span>${esc(p.city)}</span>`:''}${p.country?`<span>${esc(countryName(p.country))}</span>`:''}<span>ID ${esc(p.transponder||'—')}</span></div></div><div class="pilotProfileActions"><button class="btn secondary" data-edit-pilot="${p.id}">Редактировать</button><button class="btn danger subtleDanger" data-delete-pilot="${p.id}">Удалить</button></div></article>`).join(''):`<div class="card empty">Создайте первый профиль пилота.</div>`}</div></section>`;}

function settingsView(){return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">СИСТЕМА</div><h1>Настройки</h1><p>Единый визуальный язык, звук и технические параметры Legion RX.</p></div></div><div class="settingsGrid">
 <article class="card settingGroup"><h3>${uiIcon('settings','widgetIcon')} Интерфейс</h3><div class="toggleRow"><span>Тёмная тема</span><input class="toggle" id="darkToggle" type="checkbox" ${state.settings.theme==='dark'?'checked':''}></div><div class="field" style="margin-top:12px"><label>Язык интерфейса</label><select id="langSelect"><option value="ru" ${state.settings.lang==='ru'?'selected':''}>Русский</option><option value="en" ${state.settings.lang==='en'?'selected':''}>English</option></select></div><p>Светлая тема применяется и к пульту гонки.</p></article>
 <article class="card settingGroup designLabCard"><h3>${uiIcon('settings','widgetIcon')} Design Lab</h3><p>Живая настройка геометрии интерфейса без правки CSS.</p><div class="designLabSample"><span></span><span></span><span></span></div><button class="btn primary" data-action="open-design-lab">Открыть Design Lab</button></article>
 <article class="card settingGroup"><h3>${uiIcon('bluetooth','widgetIcon')} LapWiz</h3><div class="toggleRow"><span>Блип при принятом проходе</span><input class="toggle" id="soundToggle" type="checkbox" ${state.settings.lapSound?'checked':''}></div><div class="field" style="margin-top:12px"><label>Минимальное время круга, сек</label><input id="settingsMinLap" type="number" min="1" max="60" value="${state.settings.minLapSec}"></div><div class="btnRow" style="margin-top:12px">${lapwiz.connected?`<button class="btn secondary" data-action="lap-disconnect">Отключить LapWiz</button>`:`<button class="btn primary" data-action="lap-connect">Подключить LapWiz</button>`}<button class="btn secondary" data-action="test-bleep">Тест Bleep</button></div><p>Твой Bleep звучит только на валидном проходе зарегистрированного транспондера.</p></article>
 <article class="card settingGroup"><h3>${uiIcon('mic','widgetIcon')} Диктор гонки</h3><div class="toggleRow"><span>Вся озвучка диктора</span><input class="toggle" id="announcerToggle" type="checkbox" ${state.settings.announcerEnabled?'checked':''}></div><div class="toggleRow"><span>Загруженные имена пилотов</span><input class="toggle" id="pilotVoiceToggle" type="checkbox" ${state.settings.pilotVoiceEnabled?'checked':''}></div><div class="toggleRow"><span>Вызов пилотов на старт</span><input class="toggle" id="voiceStartCallToggle" type="checkbox" ${state.settings.voiceStartCall?'checked':''}></div><div class="toggleRow"><span>Новый лучший круг</span><input class="toggle" id="voiceBestLapToggle" type="checkbox" ${state.settings.voiceBestLap?'checked':''}></div><div class="toggleRow"><span>Финиш пилота</span><input class="toggle" id="voiceFinishToggle" type="checkbox" ${state.settings.voiceFinish?'checked':''}></div><div class="toggleRow"><span>Результаты заезда</span><input class="toggle" id="voiceResultsToggle" type="checkbox" ${state.settings.voiceResults?'checked':''}></div><div class="toggleRow"><span>Служебные сообщения</span><input class="toggle" id="voiceServiceToggle" type="checkbox" ${state.settings.voiceService?'checked':''}></div><div class="field" style="margin-top:12px"><label>Прогрев / проверка транспондеров, мин</label><select id="settingsWarmupMinutes">${[5,4,3,2,1].map(n=>`<option value="${n}" ${Number(state.settings.warmupMinutes||2)===n?'selected':''}>${n} мин</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>Начать отсчёт с секунды</label><input id="settingsCountdown" type="number" min="1" max="10" value="${state.settings.countdownSec}"></div><p>За минуту до старта: предупреждение → вызов → имена. Затем «Хорошей гонки» → выбранный отсчёт до 1 → HORN. Лучшее время остаётся на экране и цифрами не озвучивается.</p><p>Файлы имён хранятся только на устройстве. Интернет и внешние сервисы не используются.</p><div class="offlineStatusLine"><div class="audioStatusPill ${announcer.unlocked?'ready':''}"><i></i>${announcer.unlocked?'ЗВУК ГОТОВ':'ЗВУК НУЖНО ВКЛЮЧИТЬ'}</div></div><div class="offlineReadyBox ${offlineReady.ready?'ready':offlineReady.preparing?'preparing':'error'}" data-offline-ready><i></i><span><b>${offlineReady.ready?'OFFLINE READY ✓':offlineReady.preparing?'ПОДГОТОВКА OFFLINE…':'OFFLINE НЕ ГОТОВ'}</b><small class="offlineMeta">${offlineReady.ready?`${offlineReady.total}/${offlineReady.total} файлов · можно работать без интернета`:`${Math.min(offlineReady.completed,offlineReady.total)}/${offlineReady.total} файлов`}</small></span></div><div class="btnRow"><button class="btn primary" data-action="audio-enable">Включить звук</button><button class="btn secondary" data-action="offline-prepare">Проверить / подготовить OFFLINE</button><button class="btn secondary" data-action="test-good-race">Тест «Хорошей гонки»</button><button class="btn secondary" data-action="test-start-horn">Тест HORN</button></div></article>
 <article class="card settingGroup"><h3>${uiIcon('flag','widgetIcon')} Заезды по умолчанию</h3><div class="formatRuleGrid compactRules">
  <section class="ruleBox"><div class="ruleBoxHead"><b>Квалификация</b></div><div class="formGrid"><div class="field"><label>Режим</label><select id="settingsQLimit"><option value="time" ${state.settings.qualificationLimitType==='time'?'selected':''}>По времени</option><option value="laps" ${state.settings.qualificationLimitType==='laps'?'selected':''}>По кругам</option></select></div><div class="field"><label>Минуты</label><input id="settingsQMin" type="number" value="${state.settings.qualificationMinutes}"></div><div class="field"><label>Круги</label><input id="settingsQLaps" type="number" value="${state.settings.qualificationLaps}"></div></div></section>
  <section class="ruleBox"><div class="ruleBoxHead"><b>Финалы / LCQ</b></div><div class="formGrid"><div class="field"><label>Режим</label><select id="settingsFLimit"><option value="laps" ${state.settings.finalLimitType==='laps'?'selected':''}>По кругам</option><option value="time" ${state.settings.finalLimitType==='time'?'selected':''}>По времени</option></select></div><div class="field"><label>Круги</label><input id="settingsFLaps" type="number" value="${state.settings.finalLaps}"></div><div class="field"><label>Минуты</label><input id="settingsFMin" type="number" value="${state.settings.finalMinutes}"></div></div></section>
 </div><button class="btn primary" style="margin-top:12px" data-action="save-settings">Сохранить настройки</button></article>
 <article class="card settingGroup"><h3>О приложении</h3><p><b>Legion RX 4.2.0 CLEAN FULL APP RC2</b></p><p>Полная CLEAN-сборка: текущие пульты RallyCross и Free Practice сохранены, а LapWiz, спортивные правила, хранение, звук и режимы физически разделены по модулям. Rally Sprint и Classic RC остаются отдельными будущими модулями.</p><div class="list"><div class="listRow"><div class="grow"><b>Диктор старта</b><div class="sub">работает · 2 сценария</div></div><span class="badge liveBadge">ГОТОВО</span></div><div class="listRow"><div class="grow"><b>Ралли-спринт / Classic RC</b><div class="sub">спортивные модули ещё не реализованы</div></div><span class="badge soon">СКОРО</span></div><div class="listRow"><div class="grow"><b>Автоматизация / позиции / Broadcast</b><div class="sub">следующие слои общего диктора</div></div><span class="badge soon">СКОРО</span></div></div></article>
 </div></section>`;}

function syncRaceRuleFields(){const q=$('#qLimitType')?.value||'time',f=$('#finalLimitType')?.value||'laps';$$('[data-rule-field="q-time"]').forEach(x=>x.classList.toggle('inactiveRule',q!=='time'));$$('[data-rule-field="q-laps"]').forEach(x=>x.classList.toggle('inactiveRule',q!=='laps'));$$('[data-rule-field="f-time"]').forEach(x=>x.classList.toggle('inactiveRule',f!=='time'));$$('[data-rule-field="f-laps"]').forEach(x=>x.classList.toggle('inactiveRule',f!=='laps'));}

function openDesignLab(){
 const ui={...state.settings.ui};
 const controls=[
  ['cardRadius','Карточки','px',0,32],['tileRadius','Карточки дисциплин','px',0,32],['buttonRadius','Кнопки','px',0,28],['inputRadius','Поля','px',0,24],
  ['iconRadius','Иконки / плашки','px',0,24],['heroRadius','Главный баннер','px',0,36],['widgetRadius','Виджеты пульта','px',0,28],['modalRadius','Окна','px',0,30],
  ['cardPadding','Внутренний отступ карточек','px',10,32],['sectionGap','Расстояние между блоками','px',6,28],['buttonHeight','Высота кнопок пульта','px',40,70],['contentWidth','Ширина контента на ПК','px',900,1600]
 ];
 $('#modalHost').innerHTML=`<div class="designBackdrop" id="designBackdrop"><aside class="designDrawer"><div class="designHead"><div><div class="sectionLabel">LIVE UI EDITOR</div><h2>Design Lab</h2><p>Крути значения — Legion RX меняется сразу.</p></div><button class="iconBtn" id="closeDesignLab">×</button></div>
 <div class="designScroll"><section class="designSection"><h3>Радиусы и размеры</h3>${controls.map(([key,label,unit,min,max])=>`<label class="rangeRow"><span><b>${label}</b><output id="out_${key}">${ui[key]}${unit}</output></span><input type="range" min="${min}" max="${max}" step="1" value="${ui[key]}" data-ui-token="${key}"></label>`).join('')}</section>
 <section class="designSection"><h3>Главная страница</h3><label class="field"><span>Карточек дисциплин в ряд</span><select id="designCols"><option value="3" ${ui.disciplineCols===3?'selected':''}>3 — широко</option><option value="2" ${ui.disciplineCols===2?'selected':''}>2 — крупнее</option><option value="1" ${ui.disciplineCols===1?'selected':''}>1 — вертикально</option></select></label></section>
 <section class="designSection"><h3>Быстрые пресеты радиуса</h3><div class="presetRow"><button class="btn secondary" data-radius-preset="square">Строже</button><button class="btn secondary" data-radius-preset="medium">Средне</button><button class="btn secondary" data-radius-preset="soft">Мягко</button></div></section>
 </div><div class="designFooter"><button class="btn secondary" id="resetDesignLab">Сбросить</button><button class="btn secondary" id="copyDesignJson">Показать JSON</button><button class="btn primary" id="saveDesignLab">Сохранить</button></div></aside></div>`;
 const sync=()=>{applyUiTokens(ui);document.querySelectorAll('[data-ui-token]').forEach(inp=>{const out=$(`#out_${inp.dataset.uiToken}`);if(out)out.textContent=`${ui[inp.dataset.uiToken]}px`;});};
 $$('[data-ui-token]').forEach(inp=>inp.addEventListener('input',()=>{ui[inp.dataset.uiToken]=Number(inp.value);sync();}));
 $('#designCols').addEventListener('change',e=>{ui.disciplineCols=Number(e.target.value);sync();});
 $$('[data-radius-preset]').forEach(b=>b.addEventListener('click',()=>{const p=b.dataset.radiusPreset,vals=p==='square'?{cardRadius:6,tileRadius:8,buttonRadius:6,inputRadius:6,iconRadius:8,heroRadius:10,widgetRadius:8,modalRadius:10}:p==='medium'?{cardRadius:14,tileRadius:14,buttonRadius:9,inputRadius:8,iconRadius:10,heroRadius:18,widgetRadius:12,modalRadius:14}:{cardRadius:22,tileRadius:24,buttonRadius:14,inputRadius:12,iconRadius:14,heroRadius:28,widgetRadius:18,modalRadius:22};Object.assign(ui,vals);$$('[data-ui-token]').forEach(inp=>{if(vals[inp.dataset.uiToken]!=null)inp.value=vals[inp.dataset.uiToken];});sync();}));
 $('#closeDesignLab').onclick=()=>{applyUiTokens(state.settings.ui);closeModal();};
 $('#resetDesignLab').onclick=()=>{Object.assign(ui,defaultUi);$$('[data-ui-token]').forEach(inp=>inp.value=ui[inp.dataset.uiToken]);$('#designCols').value=String(ui.disciplineCols);sync();};
 $('#saveDesignLab').onclick=()=>{state.settings.ui={...ui};save(KEYS.settings,state.settings);applyUiTokens();closeModal();toast('Дизайн сохранён');};
 $('#copyDesignJson').onclick=()=>{const text=JSON.stringify(ui,null,2);const w=window.open('','_blank','width=520,height=680');if(w){w.document.write(`<pre style="font:14px/1.5 monospace;white-space:pre-wrap;padding:20px">${esc(text)}</pre>`);w.document.close();}else toast('Разрешите всплывающее окно для JSON');};
 sync();
}

function pilotModal(existing=null,addToRace=false){
 const id=existing?.id||uid('profile'),voice=existing?.voice||null,voiceReady=voice?.status==='ready',voiceStale=voiceReady&&voice.text!==existing?.name;let pendingVoice=voice;
 $('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal"><div class="modalHead"><div><div class="sectionLabel">ПИЛОТ</div><h2>${existing?'Редактировать':'Новый профиль'}</h2></div><button class="iconBtn" id="closeModal">×</button></div><div class="formGrid"><div class="field"><label>Фамилия Имя</label><input id="mName" value="${esc(existing?.name||'')}"></div><div class="field"><label>Страна</label><select id="mCountry">${countryOptions(existing?.country||'')}</select></div><div class="field"><label>Клуб</label><input id="mClub" value="${esc(existing?.club||'')}" placeholder="Например: LegionRX"></div><div class="field"><label>Город</label><input id="mCity" value="${esc(existing?.city||'')}"></div><div class="field"><label>ID транспондера</label><input id="mTrans" inputmode="numeric" value="${esc(existing?.transponder||'')}"></div><section class="pilotVoiceBox"><div class="pilotVoiceHead"><b>ЗАПИСЬ ИМЕНИ ПИЛОТА</b><span id="pilotVoiceState" class="pilotVoiceState ${voiceStale?'stale':voiceReady?'ready':''}">${voiceStale?'ИМЯ ИЗМЕНЕНО':voiceReady?'ГОТОВО ОФЛАЙН':'НЕ ЗАГРУЖЕНО'}</span></div><input id="pilotVoiceFile" type="file" accept="audio/mpeg,audio/mp3,audio/wav,audio/x-wav,audio/ogg,.mp3,.wav,.ogg" hidden><div class="pilotVoiceActions"><button class="btn primary" id="uploadPilotVoice">${voiceReady?'Заменить файл':'Загрузить имя'}</button><button class="btn secondary" id="playPilotVoice" ${voiceReady?'':'disabled'}>▶ Прослушать</button><button class="btn danger" id="deletePilotVoice" ${voiceReady?'':'disabled'}>Удалить</button></div><div class="pilotVoiceHint">Поддерживаются MP3, WAV и OGG до 5 МБ. Запись сохраняется внутри приложения и работает полностью офлайн.</div></section></div><div class="pilotEasterHint">Если в поле «Клуб» указать <b>LegionRX</b>, в карточке включается фирменная подпись клуба.</div><div class="btnRow" style="margin-top:14px"><button class="btn primary" id="savePilotModal">Сохранить</button></div></div></div>`;
 $('#closeModal').onclick=closeModal;
 $('#uploadPilotVoice').onclick=()=>{if(!$('#mName').value.trim())return toast('Сначала введите имя пилота');$('#pilotVoiceFile').click();};
 $('#pilotVoiceFile').onchange=async e=>{const file=e.target.files?.[0],name=$('#mName').value.trim(),status=$('#pilotVoiceState');if(!file)return;if(file.size>5*1024*1024)return toast('Файл больше 5 МБ');if(!file.type.startsWith('audio/')&&!/\.(mp3|wav|ogg)$/i.test(file.name))return toast('Выберите MP3, WAV или OGG');status.className='pilotVoiceState';status.textContent='СОХРАНЕНИЕ…';try{await pilotVoices.put(id,name,file,file.name);pendingVoice={source:'local-file',fileName:file.name,text:name,status:'ready',updatedAt:new Date().toISOString()};const idx=state.pilotDb.findIndex(p=>p.id===id);if(idx>=0){state.pilotDb[idx].voice=pendingVoice;save(KEYS.pilots,state.pilotDb);}if(existing)existing.voice=pendingVoice;status.className='pilotVoiceState ready';status.textContent='ГОТОВО ОФЛАЙН';$('#playPilotVoice').disabled=false;$('#deletePilotVoice').disabled=false;$('#uploadPilotVoice').textContent='Заменить файл';toast('Запись имени сохранена');}catch(err){status.className='pilotVoiceState stale';status.textContent='ОШИБКА';toast(err.message);}finally{e.target.value='';}};
 $('#playPilotVoice').onclick=async()=>{try{const ok=await pilotVoices.play(id);if(!ok)toast('Запись имени не найдена на этом устройстве');}catch(e){toast(`Не удалось воспроизвести: ${e.message}`);}};
 $('#deletePilotVoice').onclick=async()=>{try{await pilotVoices.remove(id);pendingVoice=null;if(existing)existing.voice=null;const idx=state.pilotDb.findIndex(p=>p.id===id);if(idx>=0){state.pilotDb[idx].voice=null;save(KEYS.pilots,state.pilotDb);}$('#pilotVoiceState').className='pilotVoiceState';$('#pilotVoiceState').textContent='НЕ ЗАГРУЖЕНО';$('#playPilotVoice').disabled=true;$('#deletePilotVoice').disabled=true;$('#uploadPilotVoice').textContent='Загрузить имя';toast('Запись имени удалена');}catch(e){toast(e.message);}};
 $('#mName').addEventListener('input',()=>{const status=$('#pilotVoiceState');if(pendingVoice?.status==='ready'&&$('#mName').value.trim()!==pendingVoice.text){status.className='pilotVoiceState stale';status.textContent='НУЖНО ОБНОВИТЬ';}});
 $('#savePilotModal').onclick=()=>{const name=$('#mName').value.trim();if(!name)return toast('Введите имя');const voiceMeta=pendingVoice?.status==='ready'?{...pendingVoice,status:pendingVoice.text===name?'ready':'stale'}:pendingVoice||null;const profile={id,name,club:$('#mClub').value.trim(),city:$('#mCity').value.trim(),country:$('#mCountry').value.trim().toUpperCase(),transponder:$('#mTrans').value.trim(),photo:existing?.photo||'',voice:voiceMeta};const idx=state.pilotDb.findIndex(p=>p.id===id);if(idx>=0)state.pilotDb[idx]=profile;else state.pilotDb.push(profile);save(KEYS.pilots,state.pilotDb);if(addToRace&&state.race?.stage==='setup'&&!state.race.pilots.some(p=>p.profileId===id)){const p=makePilot({...profile,profileId:id},state.race.pilots.length+1);p.profileId=id;state.race.pilots.push(p);persistRace();}closeModal();render();};
}

function pilotPicker(){const available=state.pilotDb.filter(p=>!state.race.pilots.some(r=>r.profileId===p.id));$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal"><div class="modalHead"><div><div class="sectionLabel">БАЗА</div><h2>Добавить пилотов</h2></div><button class="iconBtn" id="closeModal">×</button></div><div class="list">${available.length?available.map(p=>`<label class="listRow"><input type="checkbox" data-pick-pilot="${p.id}"><div class="avatar">${nameInitials(p.name)}</div><div class="grow"><div class="name">${pilotNameMarkup(p)}</div><div class="sub">${clubMarkup(p.club||'','Без клуба')} · ID ${esc(p.transponder||'—')}</div></div></label>`).join(''):`<div class="empty">Все пилоты из базы уже добавлены.</div>`}</div><button class="btn primary" id="addPicked" style="margin-top:12px">Добавить выбранных</button></div></div>`;$('#closeModal').onclick=closeModal;$('#addPicked').onclick=()=>{$$('[data-pick-pilot]:checked').forEach(ch=>{const profile=state.pilotDb.find(p=>p.id===ch.dataset.pickPilot);if(profile){const p=makePilot({...profile,profileId:profile.id},state.race.pilots.length+1);p.profileId=profile.id;state.race.pilots.push(p);}});persistRace();closeModal();render();};}

function championshipModal(){$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal"><div class="modalHead"><div><div class="sectionLabel">ЧЕМПИОНАТ</div><h2>Новый чемпионат</h2></div><button class="iconBtn" id="closeModal">×</button></div><div class="formGrid"><div class="field"><label>Название</label><input id="cName" value="Legion RX Cup"></div><div class="field"><label>Сезон</label><input id="cSeason" type="number" value="${new Date().getFullYear()}"></div><div class="field"><label>План этапов</label><input id="cStages" type="number" min="1" value="6"></div></div><button class="btn primary" id="saveChamp" style="margin-top:12px">Создать чемпионат</button></div></div>`;$('#closeModal').onclick=closeModal;$('#saveChamp').onclick=()=>{const c={id:uid('champ'),name:$('#cName').value.trim()||'Legion RX Cup',season:Number($('#cSeason').value),stagesPlanned:Number($('#cStages').value)||6,stages:[],stagePlans:[],pilotIds:[]};state.championships.push(c);save(KEYS.champ,state.championships);state.activeChampionshipId=c.id;state.champTab='stages';closeModal();nav('championshipDetail');};}

function champStageModal(stageId=''){const c=activeChampionship();if(!c)return;const s=stageId?c.stagePlans.find(x=>x.id===stageId):null;const nextNo=s?.number||Math.max(0,...c.stagePlans.map(x=>Number(x.number)||0))+1;$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal"><div class="modalHead"><div><div class="sectionLabel">ЭТАП ЧЕМПИОНАТА</div><h2>${s?'Настроить этап':'Новый этап'}</h2></div><button class="iconBtn" id="closeModal">×</button></div><div class="formGrid"><div class="field"><label>Номер этапа</label><input id="stageNo" type="number" min="1" value="${nextNo}" ${s?.status==='completed'?'disabled':''}></div><div class="field"><label>Название</label><input id="stageName" value="${esc(s?.name||`Этап ${nextNo}`)}"></div><div class="field"><label>Дата</label><input id="stageDate" type="date" value="${esc(s?.date||'')}"></div><div class="field"><label>Место</label><input id="stageLocation" value="${esc(s?.location||'')}" placeholder="Трасса / город"></div></div><div class="btnRow" style="margin-top:14px"><button class="btn primary" id="saveStage">Сохранить этап</button></div></div></div>`;$('#closeModal').onclick=closeModal;$('#saveStage').onclick=()=>{const number=Number($('#stageNo').value)||nextNo;const item=s||{id:uid('stage'),status:'planned',raceId:''};item.number=number;item.name=$('#stageName').value.trim()||`Этап ${number}`;item.date=$('#stageDate').value;item.location=$('#stageLocation').value.trim();if(!s)c.stagePlans.push(item);c.stagePlans.sort((a,b)=>a.number-b.number);save(KEYS.champ,state.championships);closeModal();render();};}

function champPilotPicker(){const c=activeChampionship();if(!c)return;const selected=new Set(c.pilotIds||[]);$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal"><div class="modalHead"><div><div class="sectionLabel">СОСТАВ ЧЕМПИОНАТА</div><h2>Добавить пилотов</h2></div><button class="iconBtn" id="closeModal">×</button></div><div class="list">${state.pilotDb.length?state.pilotDb.map(p=>`<label class="listRow"><input type="checkbox" data-champ-pick="${p.id}" ${selected.has(p.id)?'checked':''}><div class="avatar">${nameInitials(p.name)}</div><div class="grow"><div class="name">${pilotNameMarkup(p)}</div><div class="sub">${clubMarkup(p.club||'','Без клуба')} · ID ${esc(p.transponder||'—')}</div></div></label>`).join(''):`<div class="empty">Сначала добавьте пилотов в общую базу.</div>`}</div><button class="btn primary" id="saveChampPilots" style="margin-top:12px">Сохранить состав</button></div></div>`;$('#closeModal').onclick=closeModal;$('#saveChampPilots').onclick=()=>{c.pilotIds=$$('[data-champ-pick]:checked').map(x=>x.dataset.champPick);save(KEYS.champ,state.championships);closeModal();render();};}

function showRaceResultsById(raceId){const r=(state.race?.id===raceId?state.race:null)||state.archive.find(x=>x.id===raceId);if(!r)return toast('Результаты этапа не найдены');const prev=state.race;state.race=r;raceResultsModal();state.race=prev;}

function archiveView(){const rows=[...state.archive].sort((a,b)=>String(b.completedAt||b.updatedAt||'').localeCompare(String(a.completedAt||a.updatedAt||'')));return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">АРХИВ</div><h1>Завершённые соревнования</h1><p>Полные снимки гонок. Их можно вернуть в работу вместе с результатами, настройками и историей заездов.</p></div></div><div class="archiveGrid">${rows.length?rows.map(r=>`<article class="card archiveCard"><div class="sectionLabel">${esc(r.eventDate||'—')}</div><h2>${esc(r.eventName)}</h2><p>${stageLabel(r.stage)} · ${r.pilots?.length||0} пилотов${r.eventLocation?` · ${esc(r.eventLocation)}`:''}</p><div class="btnRow"><button class="btn primary" data-restore-archive="${r.id}">Восстановить в работу</button><button class="btn danger" data-delete-archive="${r.id}">Удалить</button></div></article>`).join(''):`<div class="card empty">Архив пока пуст.</div>`}</div></section>`;}

function pilotLapStatsModal(pilotId,context='race',refId=''){
  let p=null,times=[],title='',meta='',statsLive=null,trackRef=null;
  if(context==='track'){
    const td=refId?(state.trackDays||[]).find(x=>String(x.id)===String(refId)):state.trackDay;if(!td)return;ensureTrackDayState(td);trackRef=td;p=trackPilot(td,pilotId);const l=td.live?.[pilotId]||blankTrackLive();statsLive=l;times=lapArray(l);title=td.name;meta=`Track Day · ${td.date||''}`;
  }else if(context==='raceEvent'){
    const raw=findRawEvent(refId);if(!raw)return;p=getPilot(state.race,pilotId);const l=raw.lapStats?.[pilotId]||{};times=lapArray(l);title=raw.label||'Заезд';meta=state.race?.eventName||'RallyCross';
  }else{
    const ev=currentEvent(state.race),raw=ev?findRawEvent(ev.key):null;p=getPilot(state.race,pilotId);let l=state.session?.live?.[pilotId];if(!l&&raw?.lapStats?.[pilotId])l=raw.lapStats[pilotId];times=lapArray(l);title=ev?.label||'Текущий заезд';meta=state.race?.eventName||'RallyCross';
  }
  if(!p)return;const s=lapSummary({lapTimes:times}),trackMode=context==='track';
  const rows=times.map((ms,i)=>{let cls='',tag='';if(ms===s.best){cls='lapBest';tag='ЛУЧШИЙ';}else if(ms===s.worst){cls='lapWorst';tag='ХУДШИЙ';}else if(i===s.avgIndex){cls='lapAverage';tag='≈ СРЕДНИЙ';}return `<tr class="${cls}"><td>${i+1}</td><td><b>${fmtMs(ms)}</b></td><td>${tag}</td>${trackMode?`<td class="lapJudgeCell"><button class="lapRemoveBtn" type="button" data-track-lap-remove="1" data-track-id="${esc(trackRef?.id||'')}" data-pilot-id="${esc(p.id)}" data-lap-index="${i}" data-lap-ms="${ms}">УБРАТЬ КРУГ</button></td>`:''}</tr>`;}).join('');
  const corrections=trackMode?trackDayCorrectionLog(trackRef,p.id):[];
  const correctionHtml=trackMode&&corrections.length?`<div class="lapCorrectionLog"><div class="sectionLabel">КОРРЕКЦИИ СУДЬИ</div>${corrections.slice().reverse().map(c=>`<div><span>Круг ${Number(c.lapNumber||0)} · ${fmtMs(Number(c.lapMs))}</span><small>${new Date(c.removedAt).toLocaleString('ru-RU')}</small></div>`).join('')}</div>`:'';
  $('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal lapStatsModal"><div class="modalHead"><div><div class="sectionLabel">СТАТИСТИКА КРУГОВ</div><h2>${pilotNameMarkup(p)}</h2><p>${esc(meta)} · ${esc(title)}</p></div><button class="iconBtn" id="closeModal">×</button></div>${trackMode?`<div class="lapJudgeNote">Судья может убрать ошибочно засчитанный круг. Он исчезнет из официальной статистики, BEST/AVG/LAST и число кругов пересчитаются автоматически. Факт коррекции останется в журнале.</div>`:''}<div class="lapSummaryGrid"><div class="best"><span>ЛУЧШИЙ</span><b>${fmtMs(s.best)}</b></div><div class="average"><span>СРЕДНИЙ</span><b>${fmtMs(s.avg)}</b></div><div class="worst"><span>ХУДШИЙ</span><b>${fmtMs(s.worst)}</b></div><div><span>КРУГОВ</span><b>${s.count}</b></div>${trackMode?`<div class="pitMetric"><span>PIT</span><b>${statsLive?.pitCount||0}</b></div><div class="pitMetric"><span>В БОКСАХ</span><b>${fmtClock(trackPitTotalMs(statsLive,trackRef))}</b></div>`:''}</div><div class="tableWrap lapTableWrap"><table class="table"><thead><tr><th>Круг</th><th>Время</th><th>Отметка</th>${trackMode?'<th>Судья</th>':''}</tr></thead><tbody>${rows||`<tr><td colspan="${trackMode?4:3}">Пока нет завершённых кругов.</td></tr>`}</tbody></table></div>${correctionHtml}</div></div>`;$('#closeModal').onclick=closeModal;
  if(trackMode)$$('[data-track-lap-remove]').forEach(b=>b.onclick=()=>{const td=(state.trackDays||[]).find(x=>String(x.id)===String(b.dataset.trackId))||(state.trackDay&&String(state.trackDay.id)===String(b.dataset.trackId)?state.trackDay:null);if(!td)return toast('Track Day не найден');const pp=trackPilot(td,b.dataset.pilotId),lapNo=Number(b.dataset.lapIndex)+1,ms=Number(b.dataset.lapMs);if(!confirm(`Убрать круг ${lapNo} (${fmtMs(ms)}) у ${pp?.name||'пилота'}?\n\nКруг будет исключён из статистики, а BEST/AVG/LAST пересчитаются.`))return;const res=removeTrackDayLap(td,b.dataset.pilotId,Number(b.dataset.lapIndex));if(!res.ok)return toast(res.error);toast(`Круг ${res.lapNumber} удалён · новый BEST ${fmtMs(res.bestLapMs)}`);pilotLapStatsModal(b.dataset.pilotId,'track',b.dataset.trackId);});
}

function trackDayReportModal(td){if(!td)return;ensureTrackDayState(td);const ranked=rankTrackPilots(td),best=trackBest(td),fixes=(td.corrections||[]).filter(c=>c?.type==='lap_removed').length;$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal trackReportModal"><div class="modalHead"><div><div class="sectionLabel">TRACK DAY · ОТЧЁТ</div><h2>${esc(td.name)}</h2><p>${esc(td.date||'')} · ${td.durationMin} мин · лучший круг ${best?`${esc(best.pilot.name)} ${fmtMs(best.ms)}`:'—'}${fixes?` · коррекций судьи ${fixes}`:''}</p></div><button class="iconBtn" id="closeModal">×</button></div><div class="trackReportList">${ranked.map((p,i)=>{const l=td.live?.[p.id]||blankTrackLive(),s=lapSummary(l);return `<button class="trackReportPilot" data-pilot-stats="${p.id}" data-stats-context="track" data-track-id="${td.id}"><strong>${i+1}</strong><span><b>${pilotNameMarkup(p)}</b><small>${l.laps||0} кругов · PIT ${l.pitCount||0}${(l.totalPitMs||0)>0?` · ${fmtClock(l.totalPitMs)}`:''}</small></span><span><small>Лучший</small><b>${fmtMs(s.best)}</b></span><span><small>Средний</small><b>${fmtMs(s.avg)}</b></span><span><small>Последний</small><b>${fmtMs(l.lastLapMs)}</b></span></button>`;}).join('')}</div></div></div>`;$('#closeModal').onclick=closeModal;bind415PilotStats();}

function raceManageModal(){const ev=currentEvent(state.race);$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal raceManageModal"><div class="modalHead"><div><div class="sectionLabel">УПРАВЛЕНИЕ ПРОГРАММОЙ</div><h2>Заезды и завершение</h2><p>${esc(ev?.label||'Нет активного заезда')}</p></div><button class="iconBtn" id="closeModal">×</button></div><div class="manageCards"><section><h3>Пропустить заезды</h3><p>Отменённый заезд сохраняется в ходе соревнования, но не требует запуска.</p><div class="manageInline"><select id="skipCount"><option value="1">1 заезд</option><option value="2">2 заезда</option><option value="3">3 заезда</option><option value="5">5 заездов</option></select><button class="btn secondary" data-race-manage-action="skip">Пропустить</button></div></section>${state.race?.stage==='qualifying'?`<section><h3>Сократить квалификацию</h3><button class="btn secondary" data-race-manage-action="cancel-round">Отменить текущую серию Q${ev?.round||''}</button><button class="btn secondary" data-race-manage-action="finish-q">Закончить квалификацию сейчас</button></section>`:''}<section class="dangerZone"><h3>Завершить соревнование</h3><p>Оставшиеся заезды будут отменены, текущий рейтинг станет итоговым. После этого соревнование можно отправить в архив.</p><button class="btn danger" data-race-manage-action="finish-all">Завершить спортивную часть</button></section></div></div></div>`;$('#closeModal').onclick=closeModal;$$('[data-race-manage-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.raceManageAction;if(a==='skip')return skipRaceEvents(Number($('#skipCount')?.value||1));if(a==='cancel-round')return cancelCurrentQualRound();if(a==='finish-q')return finishQualificationNow();if(a==='finish-all')return forceFinishCompetition();});}

function trackDaySetupView(){
  const td=state.trackDay&&state.trackDay.status!=='finished'?state.trackDay:newTrackDayDraft();
  if(!state.trackDay||state.trackDay.status==='finished'){state.trackDay=td;persistTrackDays();}
  const selected=new Set(td.pilotIds||[]);
  const history=[...(state.trackDays||[])].sort((a,b)=>String(b.finishedAtEpoch||b.createdAt||'').localeCompare(String(a.finishedAtEpoch||a.createdAt||'')));
  return `<section class="page trackSetupPage"><div class="pageHeader"><div><div class="sectionLabel">TRACK DAY</div><h1>Свободная практика</h1><p>Независимая тренировочная сессия. Не влияет на чемпионаты и RallyCross. Ошибочные круги можно исключать судьёй из активной и сохранённой практики.</p></div>${td.status==='active'?`<button class="btn primary" data-track-action="open-active">Продолжить сессию</button>`:''}</div>
  <div class="grid grid2 trackSetupGrid">
   <article class="card"><div class="sectionLabel">СЕССИЯ</div><h2>Параметры практики</h2><div class="formGrid">
    <div class="field"><label>Название</label><input id="trackName" value="${esc(td.name||'Track Day')}"></div>
    <div class="field"><label>Дата</label><input id="trackDate" type="date" value="${esc(td.date||new Date().toISOString().slice(0,10))}"></div>
    <div class="field"><label>Продолжительность</label><select id="trackDuration">${[10,30,60,120].map(n=>`<option value="${n}" ${Number(td.durationMin)===n?'selected':''}>${n} минут</option>`).join('')}</select></div>
    <div class="field"><label>PIT при отсутствии прохода</label><select id="trackPitTimeout">${[[60,'1 минута'],[90,'1:30'],[120,'2 минуты'],[180,'3 минуты'],[0,'Выключено']].map(([v,t])=>`<option value="${v}" ${Number(td.pitTimeoutSec)===v?'selected':''}>${t}</option>`).join('')}</select></div>
    <div class="field"><label>Минимальное время круга, сек</label><input id="trackMinLapSec" type="number" min="1" max="60" step="1" value="${trackMinLapSec(td)}"></div>
    <div class="field"><label>Режим LapWiz</label><input value="Free Practice · непрерывная регистрация" disabled></div>
   </div><div class="trackInfoNote">Первый проход пилота фиксирует транспондер и точку начала. Со второго прохода считаются полноценные круги. Проходы быстрее выбранного минимального времени круга игнорируются как ложные/повторные и не создают круг. Если пилот не появляется на засечке дольше выбранного PIT-таймаута, незавершённый круг сбрасывается и статус меняется на PIT. Первый проход после возвращения = PIT OUT и новая точка отсчёта.</div></article>
   <article class="card"><div class="pageHeader compactHeader"><div><div class="sectionLabel">УЧАСТНИКИ</div><h2>Кто едет сегодня</h2></div><span class="badge">${selected.size} выбрано</span></div>
    <div class="trackPilotPicker">${state.pilotDb.length?state.pilotDb.map(p=>`<label class="trackPilotCheck"><input type="checkbox" data-track-pilot="${p.id}" ${selected.has(p.id)?'checked':''}><span class="avatar">${nameInitials(p.name)}</span><span><b>${pilotNameMarkup(p)}</b><small>${clubMarkup(p.club||'','Без клуба')} · ID ${esc(p.transponder||'—')}</small></span></label>`).join(''):`<div class="empty">В общей базе пока нет пилотов. Сначала добавьте их в разделе «Пилоты».</div>`}</div>
    <div class="btnRow" style="margin-top:14px"><button class="btn secondary" data-track-action="select-all">Выбрать всех</button><button class="btn primary" data-track-action="start" ${state.pilotDb.length?'':'disabled'}>Запустить практику</button></div>
   </article>
  </div>
  <div class="homeSectionHead modulesHead"><div><div class="sectionLabel">ИСТОРИЯ</div><h2>Сохранённые Track Day</h2></div></div>
  <div class="archiveGrid trackArchiveGrid">${history.length?history.map(t=>`<article class="card archiveCard"><div class="sectionLabel">${esc(t.date||'—')} · ${Number(t.durationMin||0)} мин</div><h2>${esc(t.name||'Track Day')}</h2><p>${t.pilots?.length||0} пилотов · ${Object.values(t.live||{}).reduce((s,l)=>s+Number(l.laps||0),0)} кругов</p><div class="btnRow"><button class="btn primary" data-track-report="${t.id}">Отчёт</button><button class="btn danger" data-track-delete="${t.id}">Удалить</button></div></article>`).join(''):`<div class="card empty">Пока нет завершённых Track Day.</div>`}</div>
  </section>`;
}

function trackDayHeader(td){const lapAction=lapwiz.connected?'data-action="lap-disconnect"':'data-track-action="lap-connect"';return `<header class="raceConsoleHeader"><button class="raceBrand" data-track-action="home"><strong>LEGION <i>RX</i></strong><small>Track Day · Free Practice</small></button><div class="raceHeadInfo"><div class="headCell"><span>${raceSvg('timer')}</span><div><b>${esc(td.name)}</b><small>СЕССИЯ</small></div></div><div class="headCell"><span>${raceSvg('users')}</span><div><b>${td.pilots?.length||0}</b><small>ПИЛОТОВ</small></div></div><div class="headCell"><span>${raceSvg('clock')}</span><div><b>${td.durationMin} мин</b><small>ЛИМИТ · MIN ${trackMinLapSec(td)}с · PIT ${trackPitTimeoutLabel(td)}</small></div></div><div class="headClock"><b id="trackClock">${new Date().toLocaleTimeString('ru-RU',{hour12:false})}</b><small>ВРЕМЯ</small></div></div><div class="raceHeadStatus compactHeadControls"><button class="consolePill ${lapwiz.connected?'ok':''}" ${lapAction} title="${lapwiz.connected?'Отключить':'Подключить'} LapWiz">${raceSvg('bluetooth')}<span>${lapwiz.connected?'LapWiz подключён':'Подключить LapWiz'}</span></button><span class="consolePill ${td.status==='active'?'live':'disabled'}" title="${td.status==='active'?'Практика идёт':'Сессия завершена'}">${raceSvg('play')}<span>${td.status==='active'?'Практика идёт':'Сессия завершена'}</span></span><button class="squareConsoleBtn" data-track-action="setup" title="Настройки Track Day">${raceSvg('settings')}</button></div></header>`;}

